import { execution } from '@dynatrace-sdk/automation-utils';


export default async function ({ execution_id }) {
  const exec = await execution(execution_id);

  const ex = await fetch(`/platform/automation/v1/executions/${execution_id}`);
  const data = await ex.json();
  const event = data.params?.event || {};
  const problemTitle = event['event.name'] || 'Unknown problem';
  const problemId = event['event.id'] || 'N/A';
  const status = event['event.status'] || 'OPEN';
  const affectedEntities = (event['affected_entity_ids'] || []).join(', ') || 'N/A';
  const rootCause = event['root_cause_entity_name'] || 'Unknown';
  const startTime = event['event.start'] || new Date().toISOString();
  const dtUrl = event['dt.davis.mute_url']?.replace('/mute', '') || '';
  const deployment = await exec.result('fetch_event_details');
  console.log(deployment.records[0]["lookup.deployment.url"])

  return {
    deploymentUrl: deployment.records[0]["lookup.deployment.url"],
    problemTitle,
    problemId,
    status,
    affectedEntities,
    rootCause,
    startTime,
    dtUrl
  };
}

import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ execution_id }) {
  const exec = await execution(execution_id);
  const result = await exec.result('extract_event_details');

  // ↓↓↓ paste from your VM's overview notebook ↓↓↓
  const GITLAB_USER = "userN";
  const GITLAB_PAT  = "<your GitLab PAT>";
  // ↑↑↑ paste from your VM's overview notebook ↑↑↑

  // Which service's bad release to roll back. Match the service that's
  // failing in your VM:
  const SERVICE = "payment-service";
  // Alternatives: "order-service", "inventory-service"

  // deploymentUrl is the GitLab pipeline that shipped the bad release:
  //   "https://gitlab.34.140.133.0.nip.io/user1/quickcart/-/pipelines/12"
  // Pull the base URL + project path from it so the same workflow works no
  // matter which VM fired the event.
  const m = result.deploymentUrl.match(
    /^(https?:\/\/[^/]+)\/(.+)\/-\/pipelines\/\d+/
  );
  if (!m) {
    throw new Error(`Could not parse deploymentUrl: ${result.deploymentUrl}`);
  }
  const [, gitlabBase, projectPath] = m;

  // GitLab "create pipeline" API — the .gitlab-ci.yml runs the bad-release
  // jobs whenever BAD_RELEASE_SERVICE is set; ACTION=rollback restores it.
  const url = `${gitlabBase}/api/v4/projects/${encodeURIComponent(projectPath)}/pipeline`;

  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Accept":        "application/json",
      "Content-Type":  "application/json",
      "PRIVATE-TOKEN": GITLAB_PAT,
    },
    body: JSON.stringify({
      ref: "main",
      variables: [
        { key: "BAD_RELEASE_SERVICE", value: SERVICE },
        { key: "ACTION",              value: "rollback" },
      ],
    }),
  });

  const text = await response.text();
  console.log(`GitLab create pipeline ${response.status}: ${text}`);

  let pipelineUrl = null;
  try { pipelineUrl = JSON.parse(text).web_url || null; } catch (e) { /* non-JSON error body */ }

  return {
    status:   response.status,
    success:  response.status === 201,
    gitlabBase, projectPath, service: SERVICE, user: GITLAB_USER,
    pipelineUrl,
    body:     text,
  };
}
